// 0 on the valley floor, rising to 1 up the walls on both sides; the valley winds along X
const a = 3 + 2.39996 * seed, b = 0.88 + 3.88322 * seed; // the bends' phases, a golden angle further per seed
const zc = size * (0.06 * sin(TAU * 0.85 * x / size + a) + 0.025 * sin(TAU * 1.9 * x / size + b));
return smoothstep(0.07, 0.34, abs(z - zc) / size);

// where gullies reach the floor: water of 20 to 2000 cells at the foot of the walls
const n = Math.log(1 + (Math.exp(drainage) - 1) / (cell * cell));
return smoothstep(3, 5.5, n) * (1 - smoothstep(7.5, 9.5, n)) * (1 - smoothstep(0.02, 0.15, mask));

// the fans spread out from the foot of the walls over the floor, thinning towards the middle, not up the walls
const a = 3 + 2.39996 * seed, b = 0.88 + 3.88322 * seed; // the bends' phases, a golden angle further per seed
const d = abs(z - size * (0.06 * sin(TAU * 0.85 * x / size + a) + 0.025 * sin(TAU * 1.9 * x / size + b))) / size;
return clamp(2 * fan, 0, 1) * (1 - smoothstep(0.03, 0.2, mask)) * smoothstep(0.01, 0.07, d);

// gullies on the walls where the water of 7 to 1100 cells gathers
const cells = (Math.exp(drainage) - 1) / (cell * cell);
return smoothstep(2, 7, Math.log(1 + cells)) * smoothstep(0.05, 0.4, mask);

