// water flow 0..1: the cells draining through each sample, on a log scale over the whole field
const cells = (Math.exp(drainage) - 1) / (cell * cell);
return clamp(Math.log(1 + cells) / Math.log(1 + size * size / (cell * cell)), 0, 1);

params.code:
// the largest rise from one point of the course to the next (negative: it falls all the way)
const pts = primpoints(0, 0);
let rise = -Infinity;
for (let i = 1; i < pts.length; i++) rise = Math.max(rise, point(0, 'P', pts[i])[1] - point(0, 'P', pts[i - 1])[1]);
f@rise = rise;

